function useHelpNotifications(helpRequests, userId, options = {}) {
	const { settings, addToast } = useNotifications();
	const { enabled = true, unattendedThresholdMinutes = 15 } = options;
	const checkUnattendedRequests = useCallback(() => {
		if (!enabled || !settings.enabled || !settings.helpRequests) return;
		const now = Date.now();
		const unattended = helpRequests.filter((request) => request.responders.length === 0 && now - new Date(request.createdAt).getTime() > unattendedThresholdMinutes * 6e4);
		if (unattended.length > 0) addToast({
			type: "warning",
			title: "Запросы без ответа",
			message: `${unattended.length} запросов помощи ждут ответа уже более ${unattendedThresholdMinutes} мин.`,
			duration: 0,
			action: {
				label: "Открыть помощь",
				onClick: () => {
					window.location.href = "/help";
				}
			}
		});
	}, [
		enabled,
		settings.enabled,
		settings.helpRequests,
		helpRequests,
		unattendedThresholdMinutes,
		addToast
	]);
	const checkMyResponses = useCallback((newRequests, previousCount) => {
		if (!userId || !settings.enabled) return;
		if (newRequests.filter((request) => request.responders.some((responder) => responder.userId === userId) && request.responders.length > 0).length > previousCount) addToast({
			type: "success",
			title: "Отклик на помощь",
			message: "Вы откликнулись на запрос помощи",
			duration: 3e3
		});
	}, [
		userId,
		settings.enabled,
		addToast
	]);
	useEffect(() => {
		const interval = setInterval(checkUnattendedRequests, 6e4);
		return () => clearInterval(interval);
	}, [checkUnattendedRequests]);
	return {
		checkUnattendedRequests,
		checkMyResponses
	};
}
function useAbsenceNotifications(absences, userRole, options = {}) {
	const { settings, addToast } = useNotifications();
	const { enabled = true } = options;
	const checkPendingAbsences = useCallback(() => {
		if (!enabled || !settings.enabled || !settings.absenceApprovals) return;
		if (userRole !== "officer" && userRole !== "head" && userRole !== "sysadmin") return;
		const pending = absences.filter((absence) => absence.status === "pending");
		if (pending.length > 0) addToast({
			type: "info",
			title: "Ожидают подтверждения",
			message: `${pending.length} отсутствий ждут вашего решения`,
			duration: 0,
			action: {
				label: "Открыть отсутствия",
				onClick: () => {
					window.location.href = "/absences";
				}
			}
		});
	}, [
		enabled,
		settings.enabled,
		settings.absenceApprovals,
		absences,
		userRole,
		addToast
	]);
	useEffect(() => {
		const interval = setInterval(checkPendingAbsences, 12e4);
		return () => clearInterval(interval);
	}, [checkPendingAbsences]);
	return { checkPendingAbsences };
}
function usePvpNotifications(activeMatch, disputedMatch, options = {}) {
	const { settings, addToast } = useNotifications();
	const { enabled = true } = options;
	const checkDisputedMatch = useCallback(() => {
		if (!enabled || !settings.enabled || !settings.pvpMatches) return;
		if (disputedMatch) addToast({
			type: "error",
			title: "Спорный матч",
			message: "Результаты матча расходятся. Требуется вмешательство офицера.",
			duration: 0,
			action: {
				label: "Открыть PvP",
				onClick: () => {
					window.location.href = "/pvp";
				}
			}
		});
	}, [
		enabled,
		settings.enabled,
		settings.pvpMatches,
		disputedMatch,
		addToast
	]);
	const notifyMatchComplete = useCallback((match) => {
		if (!settings.enabled || !settings.pvpMatches) return;
		addToast({
			type: "success",
			title: "Матч завершён",
			message: `${match.playerOne.nickname} vs ${match.playerTwo.nickname}`,
			duration: 5e3
		});
	}, [
		settings.enabled,
		settings.pvpMatches,
		addToast
	]);
	useEffect(() => {
		checkDisputedMatch();
	}, [checkDisputedMatch]);
	return {
		checkDisputedMatch,
		notifyMatchComplete
	};
}
